start.filterFormula:
AND(
ISCHANGED({!$Record.StageName}),
OR(
/* Condition 1 :  Opportunity is moving into Stage 4 or 5 */
ISPICKVAL({!$Record.StageName}, "4 - Negotiate"),
ISPICKVAL({!$Record.StageName}, "5 - Signed/PO in"),
/* Condition 2 : Opportunity is moving to Lost from any stage except Stage 1 */
AND(
ISPICKVAL({!$Record.StageName}, "Lost"),
NOT(ISPICKVAL(PRIORVALUE({!$Record.StageName}), "1 - Qualification"))
)
)
)
